const rows = $input.all();

// ดึงทุกแถวจาก sheet ไม่ใช่แค่แถวแรก
const sheetRows = [];
try {
  const all = $('Get row(s) in sheet').all();
  if (all && all.length > 0) {
    all.forEach(item => {
      if (item.json && !item.json.error) sheetRows.push(item.json);
    });
  }
} catch (e) {}

// รวม productFields จากทุกแถว
const productFields = [];
sheetRows.forEach(sheetData => {
  Object.entries(sheetData)
    .filter(([key]) => key.startsWith('ชื่อสินค้า#'))
    .forEach(([_, val]) => {
      if (val) productFields.push(val);
    });
});

function findMatch(keyword) {
  if (!keyword || productFields.length === 0) return null;
  const found = productFields.find(val =>
    val.toString().includes(keyword.toString().trim())
  );
  return found || null;
}

return rows.map(item => {
  const row = { ...item.json };
  if (row.row === 2 && row.T1_B != null) {
    row.T1_B = findMatch(row.T1_B) ?? row.T1_B;
  }
  return { json: row };
});

