// === Combine Machines: รวมชื่อเครื่องจาก Sheet 1 + Sheet 2 แล้วลบค่าซ้ำ ===

const sheet1 = $('Read Sheet 2').all();   // มีคอลัมน์ "เครื่อง"
const sheet2 = $('Read Sheet 1').all();   // มีคอลัมน์ "เครื่องจักร"

// ทำให้รูปแบบรหัสเครื่องเหมือนกัน เช่น PF8-8 -> PF8/8
// ถ้าไม่ต้องการให้แปลง ให้ลบ .replace(/-/g, '/') ออก
const normalize = (v) =>
  (v === undefined || v === null) ? '' : String(v).trim().replace(/-/g, '/');

const set = new Set();
for (const it of sheet1) { const c = normalize(it.json['เครื่อง']);     if (c) set.add(c); }
for (const it of sheet2) { const c = normalize(it.json['เครื่องจักร']); if (c) set.add(c); }

const machine = [...set];   // เช่น ["PF8/7", "PF8/8"]

return [{ json: { machine } }];

function getBinary(nodeName) {
  try {
    const items = $items(nodeName);
    if (items && items.length > 0 && items[0].binary) {
      return items[0].binary;
    }
  } catch (e) {}
  return null;
}

const incomingBinary = getBinary('Code in JavaScript4');
const machine = $('Combine Machines').first().json.machine || [];

const normalize = (v) =>
  (v === undefined || v === null) ? '' : String(v).trim().replace(/-/g, '/');

const machineSet = new Set(machine.map(normalize));
const sheet3 = $input.all();   // ทุกแถวจาก Read Sheet 3

const MACHINE_COL = 'Machine';
const NAME_COL    = 'Full_name';

const SEP = ' | ';

// ตัดให้เหลือ 4 ช่อง: ชื่อ | ประเภท | น้ำหนัก | สี   (ตัดช่องสุดท้าย เช่น ขึ้นเดี่ยว/ขึ้นคู่ ทิ้ง)
const toParts = (raw) => String(raw).split('|').map((p) => p.trim()).slice(0, 4);

// จับกลุ่มด้วย "ชื่อหน้า" = 3 ช่องแรก (ไม่รวมสี)
const chosen = new Map(); // front -> { trimmed, isSai }

for (const it of sheet3) {
  if (!machineSet.has(normalize(it.json[MACHINE_COL]))) continue;

  const raw = it.json[NAME_COL];
  if (raw === undefined || raw === null || String(raw).trim() === '') continue;

  const parts   = toParts(raw);
  const trimmed = parts.join(SEP);
  const front   = parts.slice(0, 3).join(SEP);
  const color   = parts[3] || '';
  const isSai   = color.endsWith('ใส');   // สีลงท้ายด้วย "ใส"

  if (!chosen.has(front)) {
    chosen.set(front, { trimmed, isSai });
  } else if (!chosen.get(front).isSai && isSai) {
    // ตัวเดิมไม่ใช่ "ใส" แต่ตัวใหม่ลงท้าย "ใส" → เปลี่ยนมาใช้ตัวใหม่
    chosen.set(front, { trimmed, isSai });
  }
  // นอกนั้นเก็บตัวแรกไว้ (กรณีไม่มี "ใส" เลย ก็ได้ตัวแรกมาแค่ตัวเดียว)
}

const produce_name = [...chosen.values()].map((v) => v.trimmed);

return [{ json: { machine, produce_name }, binary: incomingBinary }];

